/// </summary>
[ExtensionOf(tableStr(AVAEDISalesOrderInvoiceTransEntity))]
internal final class AVAEDISalesOrderInvoiceTransEntity_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void postLoad()
{
    next postLoad();

    CustInvoiceJour     custInvoiceJour;

    select firstonly custInvoiceJour
        where custInvoiceJour.InvoiceId == this.InvoiceId
        && custInvoiceJour.InvoiceDate  == this.InvoiceDate;

    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(InventTable::itemProduct(this.ItemId),  custInvoiceJour.LanguageId);
    this.AVAItemName1 = avaProductTranslation.NDXProductName1;
    this.AVAItemName2 = avaProductTranslation.NDXProductName2;

    AVAEDISalesTableOrig        ediSalesTableOrig;

    select firstonly   ediSalesTableOrig
        where ediSalesTableOrig.SalesId == custInvoiceJour.SalesId;

    this.AVAEDICommissionId = ediSalesTableOrig.NDXEDICommissionId;
}
